import { describe, expect, it } from 'vitest';
import { flowSequenceDiagram } from '../../../../src/domain/diagrams/flow-sequence.js';
import { cardOf, flowCard } from '../../../support/diagram-fixtures.js';

// RF-260, RF-508: the sequence diagram of a FLOW card, generated by code from its steps.

const named = [
  cardOf({ id: 'BR-001', type: 'BR', title: 'Basket rules' }),
  cardOf({ id: 'ENT-002', type: 'ENT', title: 'Order' }),
];

const checkout = flowCard('The shopper presses Pay.', 'An order is stored and mailed.', [
  { text: 'The basket is validated.', target: 'BR-001' },
  {
    text: 'The order is saved.',
    target: 'ENT-002',
    branches: ['A stock error shows the basket again.'],
  },
  { text: 'A receipt is written.' },
  { text: 'The mail is sent.', target: 'INT-001', status: 'Rejected' },
]);

const linesOf = (text: string): readonly string[] => text.trimEnd().split('\n');

describe('flowSequenceDiagram', () => {
  it('RF-260 draws the checkout flow (snapshot)', () => {
    expect(flowSequenceDiagram(checkout, named)).toMatchSnapshot();
  });

  it('RF-260 opens with the trigger and one participant per card the steps touch', () => {
    expect(linesOf(flowSequenceDiagram(checkout, named)).slice(0, 5)).toEqual([
      'sequenceDiagram',
      '  participant p1 as The shopper presses Pay.',
      '  participant p2 as Basket rules',
      '  participant p3 as Order',
      '  participant p4 as INT#45;001',
    ]);
  });

  it('RF-260 sends each numbered step from where the flow is to the card it touches', () => {
    const lines = linesOf(flowSequenceDiagram(checkout, named));

    expect(lines).toContain('  p1->>p2: 1. The basket is validated.');
    expect(lines).toContain('  p2->>p3: 2. The order is saved.');
  });

  it('RF-260 a step that touches no card stays with the participant the flow is at', () => {
    expect(linesOf(flowSequenceDiagram(checkout, named))).toContain(
      '  p3->>p3: 3. A receipt is written.',
    );
  });

  it('RF-260 draws each branch of a step as a numbered note', () => {
    expect(linesOf(flowSequenceDiagram(checkout, named))).toContain(
      '  Note right of p3: 2.1 A stock error shows the basket again.',
    );
  });
});

describe('flowSequenceDiagram markers and participants', () => {
  it('RF-260 marks a rejected or invalid step instead of leaving it out (ADR-005)', () => {
    const flow = flowCard('t', 'o', [
      { text: 'Rejected step.', status: 'Rejected' },
      { text: 'Bad citation.', status: 'CitationInvalid' },
    ]);
    const lines = linesOf(flowSequenceDiagram(flow, []));

    expect(lines).toContain('  p1->>p1: 1. Rejected step. #40;rejected#41;');
    expect(lines).toContain('  p1->>p1: 2. Bad citation. #40;citation invalid#41;');
  });

  it('RF-260 ends with the outcome over the participant the flow ends at', () => {
    expect(linesOf(flowSequenceDiagram(checkout, named)).at(-1)).toBe(
      '  Note over p4: Outcome#58; An order is stored and mailed.',
    );
  });

  it('RF-260 a step that comes back to a participant reuses it', () => {
    const flow = flowCard('t', 'o', [
      { text: 'a', target: 'BR-001' },
      { text: 'b', target: 'ENT-002' },
      { text: 'c', target: 'BR-001' },
    ]);
    const lines = linesOf(flowSequenceDiagram(flow, named));

    expect(lines.filter((line) => line.includes('participant'))).toHaveLength(3);
    expect(lines).toContain('  p3->>p2: 3. c');
  });
});

describe('flowSequenceDiagram ids and edge cases', () => {
  it('RF-260 a card without its flow detail opens with the card title and has no outcome', () => {
    const { flow, ...bare } = flowCard('t', 'o', [{ text: 'a' }]);
    const lines = linesOf(flowSequenceDiagram(bare, []));

    expect(flow).toBeDefined();
    expect(lines).toEqual([
      'sequenceDiagram',
      '  participant p1 as Place an order',
      '  p1->>p1: 1. a',
    ]);
  });

  it('RF-508 participant ids are generated, never taken from the card ids', () => {
    const flow = flowCard('t', 'o', [
      { text: 'a', target: 'end' },
      { text: 'b', target: 'p1' },
      { text: 'c', target: 'trigger' },
    ]);
    const lines = linesOf(flowSequenceDiagram(flow, []));

    expect(lines.slice(1, 5)).toEqual([
      '  participant p1 as t',
      '  participant p2 as end',
      '  participant p3 as p1',
      '  participant p4 as trigger',
    ]);
  });

  it('RF-508 hostile step text stays on its own line', () => {
    const flow = flowCard('t', 'o', [{ text: 'a\nend\nclick p1 href "javascript:x"; b' }]);

    expect(linesOf(flowSequenceDiagram(flow, []))).toHaveLength(4);
  });
});
